func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main_scene", main != null, "La scena principale res://main.tscn deve essere impostata e caricarsi senza errori"):
		return
	var player := find_by_name(main, "Player")
	if not check("player_node", player != null, "Nella scena principale deve essere presente un nodo chiamato Player"):
		return

	if not check("has_calc", has_function(player, "calculate_velocity"), "Lo script di Player deve contenere la funzione calculate_velocity(direction, move_speed)"):
		return
	if not check("has_input", has_function(player, "get_input_direction"), "Lo script di Player deve contenere la funzione get_input_direction()"):
		return

	# Controllo calcolo velocita su vettore diagonale non normalizzato
	var vel_diag = call_if_exists(player, "calculate_velocity", [Vector2(1.0, 1.0), 200.0], Vector2.ZERO)
	if check("diag_type", vel_diag is Vector2, "calculate_velocity deve restituire un Vector2"):
		var diag_len: float = (vel_diag as Vector2).length()
		check("diag_norm", absf(diag_len - 200.0) < 0.1, "Con direzione diagonale (1, 1) e velocita 200.0 la lunghezza risultante deve essere 200.0 (misurata: %.1f)" % diag_len)

	# Controllo con vettore fermo
	var vel_zero = call_if_exists(player, "calculate_velocity", [Vector2.ZERO, 200.0], Vector2(10, 10))
	check("zero_vel", vel_zero == Vector2.ZERO, "Con direzione Vector2.ZERO calculate_velocity deve restituire Vector2.ZERO")

	# Controllo direzione di input a riposo
	var dir_idle = call_if_exists(player, "get_input_direction", [], Vector2(99, 99))
	check("idle_dir", dir_idle == Vector2.ZERO, "Senza tasti premuti get_input_direction deve restituire Vector2.ZERO")

	# Controllo spostamento effettivo nel _process
	player.position = Vector2(200.0, 200.0)
	await hold_action("move_right", 10)
	check("moves_right", player.position.x > 200.5, "Tenendo premuta l'azione move_right il Player deve avanzare verso destra (partito da 200.0, arrivato a %.1f)" % player.position.x)
"
