@export var speed: float = 120.0
@export var target_position: Vector2 = Vector2.ZERO


func _process(delta: float) -> void:
	var direction: Vector2 = get_direction_to_target(target_position)
	if direction != Vector2.ZERO:
		rotation = direction.angle()
	global_position = step_toward(target_position, speed * delta)


func get_direction_to_target(target: Vector2) -> Vector2:
	return global_position.direction_to(target)


func step_toward(target: Vector2, delta_distance: float) -> Vector2:
	return global_position.move_toward(target, delta_distance)
"
